import newsData from '../newsData.json';
import { useParams } from 'react-router-dom';
import Contacts from '../components/Contacts';


export default function NewsDetail({ lang }) {
    const { id } = useParams();
  const newsItem = newsData.find((item) => item.id.toString() === id);

      if (!newsItem) {
    return <div className="container mt-4">Новость не найдена / News not found</div>;
    }

  return (
    <div className="py-5 text-dark bg-white" style={{ fontFamily: 'Montserrat', lineHeight: '1.7'}}>
      {/* Title + Date */}
      <div className="text-center mb-4">
        <h1 className="news-title fw-bold">
          {newsItem.title[lang]}
        </h1>
        <p className="text-dark">{newsItem.date}</p>
      </div>

      {/* Bootstrap carousel */}
{newsItem.images?.length > 0 && (
  <div id="newsImageCarousel" className="carousel slide mb-5 mx-auto" data-bs-ride="carousel" style={{ width: '90%' }}>
    <div className="carousel-inner">
      {newsItem.images.map((img, index) => (
        <div
          className={`carousel-item ${index === 0 ? 'active' : ''}`}
          key={index}
          style={{ position: 'relative' }}
        >
          <img
            loading="lazy"
            src={`${import.meta.env.BASE_URL}${img.slice(1)}`}
            className="d-block mx-auto w-100"
            alt={`news-${index}`}
            style={{ height: '480px', objectFit: 'cover' }}
          />

          {/* Dark overlay */}
          <div
            className="position-absolute top-0 start-0 w-100 h-100"
            style={{ backgroundColor: 'rgba(0,0,0,0.5)', pointerEvents: 'none', zIndex: 1 }}
          />

          {/* Caption (optional) */}
          <div className="carousel-caption d-flex flex-column justify-content-end" style={{ zIndex: 2 }}>
            <h5 className="fw-bold" style={{ fontSize: '28px' }}>
              {newsItem.title[lang]}
            </h5>
          </div>
        </div>
      ))}
    </div>

    {/* Controls */}
    {newsItem.images.length > 1 && (
      <>
        <button className="carousel-control-prev" type="button" data-bs-target="#newsImageCarousel" data-bs-slide="prev">
          <span className="carousel-control-prev-icon" aria-hidden="true" />
          <span className="visually-hidden">Previous</span>
        </button>
        <button className="carousel-control-next" type="button" data-bs-target="#newsImageCarousel" data-bs-slide="next">
          <span className="carousel-control-next-icon" aria-hidden="true" />
          <span className="visually-hidden">Next</span>
        </button>
      </>
    )}
  </div>
)}


      {newsItem.videos && (
          <div className="video-section  w-75 mx-auto" style={{ display: 'flex', flexWrap: 'wrap', gap: '20px', justifyContent: 'center', marginTop: '30px', marginBottom: '40px' }}>
                <iframe
                    width="500"
                    height="300"
                    src={newsItem.videos}
                    title="YouTube video"
                    frameBorder="0"
                    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                    allowFullScreen
                ></iframe>
            </div>
      )}

      {/* Article body */}
      <div className="mx-auto w-75" style={{ fontSize: '18px', whiteSpace: 'pre-line', marginBottom: '30px' }}>
        {newsItem.content[lang].map((line, idx) => (
          <p key={idx}>{line}</p>
        ))}
      </div>
      <hr className='text-dark my-0 mx-auto' style={{ height: '1px' }}/>
      <section id="contacts">
          <Contacts lang={lang}/>
      </section>
    </div>
  );
}